#define TAU (acos(-1.)*2.)
#define rot(n) mat2(cos(n),-sin(n),sin(n),cos(n))
#define r iResolution.xy

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{


float two = (TAU/TAU+TAU/TAU);
float pi = TAU/two;

float i_t = floor(iTime/TAU)*TAU;
float t = i_t+(-cos((iTime-i_t)/two)*pi+pi);

vec2 p=(fragCoord.xy*two-r)/r.y;
p*=TAU;

p.x = abs(p.x);
p *= rot(t);
p.x -= TAU/TAU/TAU;

p.y = abs(p.y);
p *= -rot(t/TAU);
p.x -= TAU/TAU;

p.y += p.x;
p = floor(p)+fract(p)/TAU;

p.x = abs(p.x);
p *= rot(-t*sqrt(TAU));
p.x += TAU/TAU/TAU;

p.y = abs(p.y);
p *= rot(t/TAU/TAU);
p.y += TAU/TAU;

fragColor=vec4(sin(vec3(TAU/TAU,TAU*TAU,sqrt(TAU))+length(p)*TAU-t),TAU);
}
